import{_ as a,o,c as e,ak as n}from"./chunks/framework.BNVJvTzl.js";const p=JSON.parse('{"title":"Connect your AI assistant","description":"Connect Claude, or another AI assistant, to VERA to draft proposals from your past work, staff them at the lowest cost and find the earliest start.","frontmatter":{"title":"Connect your AI assistant","description":"Connect Claude, or another AI assistant, to VERA to draft proposals from your past work, staff them at the lowest cost and find the earliest start."},"headers":[],"relativePath":"guide/ai-connector.md","filePath":"guide/ai-connector.md"}'),s={name:"guide/ai-connector.md"};function r(i,t,c,l,d,h){return o(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="connect-your-ai-assistant" tabindex="-1">Connect your AI assistant <a class="header-anchor" href="#connect-your-ai-assistant" aria-label="Permalink to &quot;Connect your AI assistant&quot;">​</a></h1><p>You can connect Claude, or another AI assistant that supports custom connectors, to VERA and work on proposals by asking in plain language. The assistant signs in as you, so it can only do what you can do.</p><p>Two things you might ask:</p><ul><li>&quot;Draft a proposal like the Acme rebrand, staffed with our lowest-cost people.&quot;</li><li>&quot;When&#39;s the earliest we could start this?&quot;</li></ul><p>The assistant reads your past projects, people and costs, builds a draft proposal in VERA, and gives you a link. You review it, change it and decide what happens next in VERA.</p><h2 id="who-can-use-it" tabindex="-1">Who can use it <a class="header-anchor" href="#who-can-use-it" aria-label="Permalink to &quot;Who can use it&quot;">​</a></h2><p>Owners and admins. An owner or admin turns the connector on for the workspace in <strong>Settings → General</strong>. Until then it is off and nobody can connect.</p><h2 id="how-to-connect" tabindex="-1">How to connect <a class="header-anchor" href="#how-to-connect" aria-label="Permalink to &quot;How to connect&quot;">​</a></h2><ol><li>Open <strong>Settings → General</strong> and turn on <strong>AI connector</strong>.</li><li>Copy the address it shows.</li><li>In Claude, add that address as a custom connector.</li><li>When Claude sends you to VERA, sign in with your VERA account and press <strong>Allow</strong>.</li></ol><h2 id="what-it-can-and-can-t-do" tabindex="-1">What it can and can&#39;t do <a class="header-anchor" href="#what-it-can-and-can-t-do" aria-label="Permalink to &quot;What it can and can&#39;t do&quot;">​</a></h2><p>It can:</p><ul><li>Read your projects, people and their cost rates, clients, disciplines and proposals, and find anyone by name, vendors included</li><li>Check whether your team has room for a proposal, week by week, and find the earliest start</li><li>Create draft proposals and change their staffing and vendor costs</li></ul><p>It can&#39;t:</p><ul><li>Turn a proposal into a project, or delete a proposal</li><li>Change a proposal once it is won, lost or turned into a project</li><li>Change projects, people, time or rates</li></ul><h2 id="what-s-shared" tabindex="-1">What&#39;s shared <a class="header-anchor" href="#what-s-shared" aria-label="Permalink to &quot;What&#39;s shared&quot;">​</a></h2><p>What the assistant reads goes to the AI service you use, so connect only an assistant you are comfortable sharing your workspace&#39;s figures with. VERA keeps a log of which tools ran and whether they worked, never what you asked. Owners and admins can see the log under <strong>Logs → AI connector</strong>, and can disconnect anyone, or turn the connector off for everyone, in <strong>Settings</strong>.</p>',16)])])}const f=a(s,[["render",r]]);export{p as __pageData,f as default};
